const { detectarPeriodo } = require('@healthradar/core');
const pregunta = $('Webhook').item.json.body.pregunta || '';
return [{ json: detectarPeriodo(pregunta) }];

const { resolverVentana } = require('@healthradar/core');
const deteccion = $('Detectar periodo en la pregunta').first().json;
const boletines = $input.all().map(i => i.json);
return [{ json: resolverVentana(deteccion, boletines) }];

const { filtrarBoletines } = require('@healthradar/core');
const periodo = $('Resolver ventana por defecto (si aplica)').first().json;
const boletines = $('Get row(s)1').all().map(i => i.json);
return filtrarBoletines(periodo, boletines).map(b => ({ json: b }));

const { filtrarClima } = require('@healthradar/core');
const periodo = $('Resolver ventana por defecto (si aplica)').first().json;
const clima = $('Get row(s)').all().map(i => i.json);
return filtrarClima(periodo, clima).map(c => ({ json: c }));

const { construirContextoPrompt } = require('@healthradar/core');
const boletines = $('Filtrar boletines del periodo').all().map(i => i.json).filter(b => !b._sin_boletines);
const clima = $('Filtrar clima del periodo').all().map(i => i.json);
const periodo = $('Resolver ventana por defecto (si aplica)').first().json;
let textoTendencia = '';
try { textoTendencia = $('Armar texto de tendencia').first().json.texto_tendencia || ''; } catch(e) {}
return [{ json: construirContextoPrompt(boletines, clima, periodo, textoTendencia) }];

const { detectarDepartamento } = require('@healthradar/core');
const pregunta = $('Webhook').item.json.body.pregunta || '';
return [{ json: detectarDepartamento(pregunta) }];

const { decidirPrediccion } = require('@healthradar/core');
const depto = $('Detectar departamento en la pregunta').first().json;
const enf = $('Detectar enfermedad en la pregunta').first().json;
const periodo = $('Resolver ventana por defecto (si aplica)').first().json;
return [{ json: decidirPrediccion(periodo, depto, enf) }];

const { armarTextoTendencia } = require('@healthradar/core');
const decision = $('Decidir si activar prediccion (Postgres)').first().json;
const filas = $input.all().map(i => i.json);
return [{ json: { texto_tendencia: armarTextoTendencia(decision, filas) } }];

const { detectarEnfermedad } = require('@healthradar/core');
const pregunta = $('Webhook').item.json.body.pregunta || '';
return [{ json: detectarEnfermedad(pregunta) }];

const { extraerNivelRiesgo } = require('@healthradar/core');
const salida = $input.first().json;
return [{ json: extraerNivelRiesgo(salida) }];

