// HU-2 (Phoenix): marca la hora de inicio para medir la latencia de toda la consulta.
// Solo agrega _t0; los demas nodos leen la pregunta con $('Webhook'), no de este item.
// Falla claro si falta el prompt externalizado (evita que el modelo responda sin instrucciones).
if (!$env.SYSTEM_PROMPT_CONEXION) throw new Error('Falta SYSTEM_PROMPT_CONEXION en infrastructure/.env (ver src/ia-ops/prompts)');
return $input.all().map(i => ({ json: { ...i.json, _t0: Date.now() } }));

// HU-2 (Phoenix): arma el span de la consulta con @healthradar/core.
const { construirTrazaPhoenix, extraerRespuestaLlm } = require('@healthradar/core');
const salida = $('Verificar cifras').first().json;
const pregunta = $('Webhook').first().json.body.pregunta || '';
let inicio; try { inicio = $('Marcar inicio (traza)').first().json._t0; } catch (e) {}
// Modelo/agente ya resueltos por el nodo 'Agregar modelo usado' (core)
const { agente, modelo_usado: modelo, proveedor } = salida;
// HU-3: datos de la busqueda semantica (para calibrar k y la distancia maxima en Phoenix)
let rag = {};
try {
  const r = $('Armar contexto RAG').first().json;
  rag = { rag_ok: r.rag_ok, rag_encontrados: r.rag_encontrados, rag_k: r.rag_k, rag_max_distancia: r.rag_max_distancia, rag_ms: r.rag_ms,
    rag_boletines: (r.rag_boletines || []).map(b => 'SE' + b.semana + '-' + b.anio + ':' + b.distancia).join(','),
    ...(r.rag_ok ? {} : { rag_motivo: r.rag_motivo }) };
} catch (e) {}
// RAG paso 3: resultado de la verificacion de cifras (para auditar falsos positivos en Phoenix)
const ver = salida._verificacion || {};
const cifras = { cifras_revisadas: ver.revisadas, cifras_sin_respaldo: ver.sin_respaldo, cifras_advertencia: !!salida.advertencia_cifras };
// Tamano aproximado del contexto enviado al modelo (para estimar tokens de entrada)
let promptChars = 0;
try { promptChars = JSON.stringify($('Consolidar boletines + clima del periodo').first().json).length; } catch (e) {}
try { promptChars += String($('Armar contexto RAG').first().json.texto_rag || '').length; } catch (e) {}
// Tokens REALES cuando respondio Kimi o GLM por HTTP (usage de la respuesta); Gemini sigue estimado
let tokens;
try {
  const nodo = agente === 1 ? 'HTTP Kimi' : agente === 2 ? 'HTTP GLM' : null;
  if (nodo) tokens = extraerRespuestaLlm($(nodo).first().json).tokens || undefined;
} catch (e) {}
const traza = construirTrazaPhoenix({
  nombre: 'nlq.consulta',
  entrada: pregunta,
  salida: salida.output,
  modelo,
  inicioMs: inicio,
  finMs: Date.now(),
  sessionId: 'healthradar-conexion',
  exito: !!salida.output,
  error: salida.output ? '' : 'Respuesta vacia del modelo',
  promptChars,
  tokens,
  metadatos: { flujo: 'Conexion', agente, proveedor, nivel_riesgo: salida.nivel_riesgo, ...rag, ...cifras }
});
return [{ json: { traza } }];

// HU-11: agrega modelo_usado (el contrato del webhook ya lo define).
// Agente que respondio = el ultimo de la cadena de failover que se ejecuto:
// 1 Kimi K3 -> 2 GLM 5.3 -> 3 Gemini -> 4 Gemini
const { modeloPorAgente } = require('@healthradar/core');
let agente = 1;
try {
  if ($('AI Agent Gemini 3').isExecuted) agente = 4;
  else if ($('AI Agent Gemini 2').isExecuted) agente = 3;
  else if ($('HTTP GLM').isExecuted) agente = 2;
} catch (e) {}
const m = modeloPorAgente(agente);
// Los nodos Gemini pueden cambiar de modelo: se lee el real del nodo que respondio
let modelo = m.modelo;
const NODO = { 3: 'Google Gemini Chat Model 2', 4: 'Google Gemini Chat Model 3' };
if (NODO[agente]) { try { modelo = String($node[NODO[agente]].parameter.modelName).replace(/^models\//, ''); } catch (e) {} }
return [{ json: { ...$input.first().json, modelo_usado: modelo, proveedor: m.proveedor, agente: m.agente } }];

// HU-12: fallaron los 4 agentes. Error limpio para el front + traza fallida en Phoenix.
const { construirErrorNlq, construirTrazaPhoenix } = require('@healthradar/core');
const { cuerpo, mensajeTecnico } = construirErrorNlq($input.first().json.error);
const pregunta = $('Webhook').first().json.body?.pregunta || '';
let inicio; try { inicio = $('Marcar inicio (traza)').first().json._t0; } catch (e) {}
const traza = construirTrazaPhoenix({
  nombre: 'nlq.consulta',
  entrada: pregunta,
  salida: '',
  modelo: 'cadena-failover',
  inicioMs: inicio,
  finMs: Date.now(),
  sessionId: 'healthradar-conexion',
  exito: false,
  error: mensajeTecnico,
  promptChars: 0,
  metadatos: { flujo: 'Conexion', agente: 0, proveedor: 'ninguno', codigo_error: cuerpo.codigo }
});
return [{ json: { cuerpo, traza } }];

// V10: arma lo que se envia por HTTP a Kimi y a GLM (logica en @healthradar/core).
const { construirMensajesChat, construirCuerpoChat } = require('@healthradar/core');
const c = $('Consolidar boletines + clima del periodo').first().json;
const body = $('Webhook').first().json.body || {};
// HU-3: contexto de la busqueda semantica ('' si no hubo o fallo)
let textoRag = ''; try { textoRag = $('Armar contexto RAG').first().json.texto_rag || ''; } catch (e) {}
// Filas de chat_mensaje (si no hay historial llega un item vacio: se descarta)
const historial = $input.all().map(i => i.json).filter(f => f && f.rol);
// El prompt viene del .env y va dentro del mensaje de usuario (igual que en los agentes)
const messages = construirMensajesChat({
  promptSistema: $env.SYSTEM_PROMPT_CONEXION,
  criterioPeriodo: c.criterio_periodo,
  cantidadBoletines: c.cantidad_boletines,
  textoBoletines: c.texto_boletines,
  textoClima: c.texto_clima,
  textoTendencia: c.texto_tendencia,
  textoRag,
  pregunta: body.pregunta,
  historial,
});
return [{ json: {
  cuerpo_kimi: construirCuerpoChat({ modelo: 'moonshotai/kimi-k3', messages }),
  cuerpo_glm: construirCuerpoChat({ modelo: 'z-ai/glm-5.3', messages }),
  mensajes_historial: messages.length - 1,
} }];

// Deja la respuesta como { output } para el IF de siempre. Respuesta vacia -> '' (pasa al siguiente modelo).
const { extraerRespuestaLlm } = require('@healthradar/core');
return [{ json: { output: extraerRespuestaLlm($input.first().json).output } }];

// GLM razona: si el razonamiento consume max_tokens, content llega nulo -> output '' -> sigue Gemini.
const { extraerRespuestaLlm } = require('@healthradar/core');
return [{ json: { output: extraerRespuestaLlm($input.first().json).output } }];

// Despues de responder: pregunta + respuesta limpia (sin marcador de riesgo). Sin sessionId no se guarda.
const { prepararGuardadoHistorial } = require('@healthradar/core');
const body = $('Webhook').first().json.body || {};
return [{ json: prepararGuardadoHistorial({ sessionId: body.sessionId, pregunta: body.pregunta, respuesta: $input.first().json.output }) }];

// HU-3: prepara la busqueda semantica. k y max_distancia son los valores de arranque del plan v2.3
// (se calibran con las trazas de Phoenix, healthradar.rag_*). Modelo y dimensiones: los MISMOS que el indexador.
const { construirExclusionBoletines } = require('@healthradar/core');
const K = 5;
const MAX_DISTANCIA = 0.35;   // = similitud minima 0.65
const pregunta = String((($('Webhook').first().json.body) || {}).pregunta || '').trim().slice(0, 2000);
let periodo = [];
try { periodo = $('Filtrar boletines del periodo').all().map(i => i.json); } catch (e) {}
return [{ json: {
  _t0: Date.now(),
  hay_pregunta: pregunta !== '',
  k: K,
  max_distancia: MAX_DISTANCIA,
  excluidos: construirExclusionBoletines(periodo),   // boletines que YA van en el contexto del periodo
  body: {
    model: 'models/gemini-embedding-001',
    content: { parts: [{ text: pregunta || ' ' }] },
    taskType: 'RETRIEVAL_QUERY',          // los boletines se indexaron como RETRIEVAL_DOCUMENT
    outputDimensionality: 768,
  },
} }];

// HU-3: valida dimension y normaliza (L2), igual que el indexador. Si no es valido, la busqueda se omite.
const MODELO = 'gemini-embedding-001';
const DIMS = 768;
const prep = $('Preparar busqueda semantica').first().json;
const r = $input.first().json || {};
const vec = r.embedding && r.embedding.values;
let ok = prep.hay_pregunta && Array.isArray(vec) && vec.length === DIMS && vec.every(Number.isFinite);
let norma = 0;
if (ok) { norma = Math.sqrt(vec.reduce((s, x) => s + x * x, 0)); ok = norma > 0; }
const motivo = ok ? '' : (!prep.hay_pregunta ? 'sin pregunta'
  : r.error ? 'HTTP/red: ' + String(r.error.message || r.error).slice(0, 120)
  : Array.isArray(vec) ? 'dimension ' + vec.length + ' != ' + DIMS : 'respuesta sin embedding');
return [{ json: {
  ok, motivo,
  embedding: ok ? JSON.stringify(vec.map(x => x / norma)) : null,   // $1
  modelo: ok ? MODELO : null,                                        // $2
  k: prep.k,                                                         // $3
  excluidos: prep.excluidos,                                         // $4
  max_distancia: prep.max_distancia,                                 // $5
} }];

// HU-3: da forma al contexto recuperado (core) y deja lo que Phoenix necesita para calibrar k y la distancia.
const { construirContextoRag } = require('@healthradar/core');
const val = $('Validar vector de la pregunta').first().json;
let t0; try { t0 = $('Preparar busqueda semantica').first().json._t0; } catch (e) {}
// Si la consulta fallo (continuar con error) llegan items sin 'resumen': se descartan.
const filas = $input.all().map(i => i.json).filter(r => r && r.resumen !== undefined);
const rag = construirContextoRag(filas);
return [{ json: {
  texto_rag: rag.texto_rag,
  rag_ok: !!val.ok,
  rag_motivo: val.motivo || '',
  rag_encontrados: rag.cantidad,
  rag_boletines: rag.boletines,
  rag_k: val.k,
  rag_max_distancia: val.max_distancia,
  rag_ms: Number.isFinite(t0) ? Date.now() - t0 : null,
} }];

// RAG paso 3: las cifras de la respuesta deben salir de los datos que vio el modelo
// (boletines del periodo, boletines recuperados, clima, tendencia, pregunta e historial).
// Falla abierta: ante cualquier error la respuesta sale igual, sin advertencia (no rompe el chat).
const { verificarCifras } = require('@healthradar/core');
const salida = $input.first().json;
let v = { revisadas: 0, sin_respaldo: [], advertencia_cifras: null };
try {
  const c = $('Consolidar boletines + clima del periodo').first().json;
  const body = $('Webhook').first().json.body || {};
  let rag = ''; try { rag = $('Armar contexto RAG').first().json.texto_rag || ''; } catch (e) {}
  let historial = []; try { historial = $('Leer historial (Postgres)').all().map(i => i.json.contenido || ''); } catch (e) {}
  v = verificarCifras(salida.output, {
    contexto: [c.texto_boletines, c.texto_clima, c.texto_tendencia, c.criterio_periodo, rag, body.pregunta, ...historial],
    metadatos: [c.cantidad_boletines],
  });
} catch (e) {}
return [{ json: { ...salida, advertencia_cifras: v.advertencia_cifras,
  _verificacion: { revisadas: v.revisadas, sin_respaldo: v.sin_respaldo.length } } }];
